import os
import subprocess

def get_git_files():
    try:
        output = subprocess.check_output(["git", "ls-files"], text=True)
        return output.splitlines()
    except Exception as e:
        print(f"Error getting git files: {e}")
        return []

def is_text_file(file_path):
    # Very basic check, can be improved
    extensions = {'.ts', '.tsx', '.js', '.jsx', '.json', '.md', '.py', '.sh', '.yml', '.yaml', '.toml', '.nix', '.html', '.css', '.jsonc', '.mdx'}
    return os.path.splitext(file_path)[1] in extensions

def generate_codebase_dump(output_file):
    files = get_git_files()
    with open(output_file, 'w', encoding='utf-8') as f:
        f.write("# Codebase Dump\n\n")
        f.write("## Project Structure\n\n")

        # We could use tree but let's just list the files for now or a simplified tree
        # For brevity, let's just start with the file contents

        for file_path in files:
            if not os.path.exists(file_path):
                continue
            if not is_text_file(file_path):
                continue

            # Skip some files that might be too large or noise
            if 'bun.lock' in file_path or 'package-lock.json' in file_path:
                continue

            try:
                size = os.path.getsize(file_path)
                if size > 100000: # Skip files larger than 100KB
                    f.write(f"### File: {file_path} (Skipped, too large: {size} bytes)\n\n")
                    continue

                f.write(f"### File: {file_path}\n\n")
                f.write("```" + (os.path.splitext(file_path)[1][1:] or "text") + "\n")
                with open(file_path, 'r', encoding='utf-8', errors='replace') as content_file:
                    f.write(content_file.read())
                f.write("\n```\n\n")
            except Exception as e:
                f.write(f"### File: {file_path} (Error reading: {e})\n\n")

if __name__ == "__main__":
    generate_codebase_dump("codebase.md")
    print("Codebase dump generated in codebase.md")

